-- KalagProMax: seed data migration
-- Generated from the 15 Base44 CSV exports the user downloaded from their
-- Base44 app, targeting the schema created in 0001_init.sql.
-- Run this AFTER 0001_init.sql, in the Supabase SQL editor (or `supabase db push`).
--
-- Decisions made while converting this data (read before running):
--
-- 1. Base44 ids are 24-character Mongo-style hex ids (e.g. "6aa8f58f..."),
--    which are not valid Postgres uuids. Every id is deterministically
--    remapped to a uuid by zero-padding it to 32 hex chars and formatting it
--    as 8-4-4-4-12 (same input -> same output, always). This keeps
--    Gap <-> GapUpdate and DirectTask <-> TaskCompletion references intact.
--
-- 2. created_by_id: Base44's internal ids (Mongo ids like
--    "6aa1c4cc72f2848a151a92c0", or service markers like
--    "service_f8a5847a-...") do not correspond to any row in this
--    project's new auth.users table and are not valid uuids either way, so
--    created_by_id is left NULL on every imported row. The original Base44
--    id is preserved as plain text in created_by instead, so the source is
--    not lost. Practical effect: task_completions rows imported this way
--    are only visible to admins (its RLS policy is
--    "created_by_id = auth.uid() OR is_admin()") until reassigned.
--
-- 3. task_completions.task_type: the real data includes the value
--    "direct" (a completion of a DirectTask), which the original Base44
--    entity schema only documented as 'event'/'shotaf'. The CHECK
--    constraint from 0001_init.sql is widened below to also allow 'direct'.
--
-- 4. Empty-string optional fields from the CSVs are imported as NULL.
--    withdrawal_requests.status is NOT NULL with a CHECK; empty status in
--    the export is imported as the schema default 'pending' (i.e. "not yet
--    decided"), matching what an empty status means in the source data.
--
-- 5. The is_sample column from the exports is not part of the new schema
--    and is dropped.
--
-- 6. Three exports were empty and have no INSERT statements below:
--    Constraint, EquipmentHolding, RecurringOverride.

begin;

-- widen the task_type check constraint to allow the real 'direct' value
alter table public.task_completions drop constraint task_completions_task_type_check;
alter table public.task_completions add constraint task_completions_task_type_check
  check (task_type in ('event', 'shotaf', 'direct'));

